    },
    {
      "name": "白月笙",
      "function": "阻碍",
      "identity": "通灵会头目",
      "description": "神秘的通灵会女头目，声称能与死者沟通，对沈清源的科学调查充满敌意"
    },
    {
      "name": "林小川",
      "function": "助力",
      "identity": "法医助手",
