    },
    {
      "name": "查尔斯·温斯顿",
      "function": "反转点",
      "identity": "英国领事馆档案管理员",
      "description": "掌握1842年档案秘密的英国人，在关键时刻提供关键线索"
    }
  ],
  "relationship_dynamics": "沈清源与各方势力形成复杂关系网：与周正德的合作中带有权力博弈，与白月笙的对立中隐藏着共同的秘密，与林小川的师徒关系体现科学传承，与查尔斯的接触揭示历史真相。所有关系都围绕通灵守则展开，最终指向1842年的历史原点。"
}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立民国上海租界背景，引入三起密室命案，沈清源发现通灵守则并开始调查",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "无水之溺",
        "core_event": "沈清源被召去调查第一起密室命案，死者是通灵会常客，死因溺毙但现场干燥无水。他在墙纸上发现七条通灵守则。",
        "emotional_tone": "悬疑紧张",
        "key_scenes": ["法医验尸发现异常", "密室现场勘查", "发现墙纸上的通灵守则"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "规则的陷阱",
        "core_event": "第二起命案发生，同样模式。沈清源逐条分析通灵守则，发现第三条'不可质疑规则'与第五条'必须验证真相'存在逻辑矛盾。",
        "emotional_tone": "困惑焦虑",
        "key_scenes": ["第二起命案现场", "规则逻辑分析", "与警察局长的争论"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "通灵会的秘密",
        "core_event": "沈清源潜入通灵会调查，遇到神秘头目白月笙。他开始怀疑凶手就是制定规则的人，但发现所有成员都坚信规则是神启。",
        "emotional_tone": "神秘诡异",
        "key_scenes": ["通灵会集会", "与白月笙对峙", "发现成员的恐惧"]
      }
    ],
    "turning_point": "第三起命案发生，沈清源在死者手中发现一张1842年的英文报纸碎片，上面有通灵守则的早期版本。"
  },
  "act_two": {
    "description": "深入调查1842年档案，沈清源发现自己正在不自觉执行第六条规则，陷入更深的困境",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "南京条约的阴影",
        "core_event": "沈清源通过英国领事馆档案管理员查尔斯找到1842年《南京条约》签订当日的档案，发现通灵守则最早出现在一份外交备忘录中。",
        "emotional_tone": "震惊困惑",
        "key_scenes": ["档案室查阅", "发现1842年文件", "历史背景揭示"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "第六条的诅咒",
        "core_event": "沈清源意识到自己正在不自觉地执行第六条规则'独自承担真相'，他开始出现幻觉和记忆混乱，怀疑自己也被规则控制。",
        "emotional_tone": "恐惧绝望",
        "key_scenes": ["自我反思", "幻觉体验", "向助手求助"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "家族的秘密",
        "core_event": "沈清源发现自己的祖父曾在1842年作为翻译参与《南京条约》谈判，而通灵守则实际上是当时用来控制谈判代表心理状态的工具。",
        "emotional_tone": "震撼觉醒",
        "key_scenes": ["家族档案发现", "祖父日记解读", "历史真相初现"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "心理暗示的武器",
        "core_event": "第二次认知反转：通灵守则并非超自然力量，而是一种基于心理学的集体暗示技术，通过特定频率的声音和视觉刺激触发大脑特定反应。",
        "emotional_tone": "恍然大悟",
        "key_scenes": ["科学实验验证", "声波频率测试", "心理机制揭示"]
      }
    ],
    "turning_point": "第三次认知反转：1842年的档案显示，通灵守则最初是英国心理学家开发的'心理武器'，用于在谈判中让对手产生溺水幻觉从而屈服，但后来失控成为真正的杀人工具。"
  },
  "act_three": {
    "description": "破解所有谜题，揭示硬核科学解释，解决密室命案并打破规则循环",
    "key_chapters": [
      {
        "chapter_number": 8,
        "chapter_title": "密室的真相",
        "core_event": "沈清源发现密室手法：凶手利用特定频率的次声波和催眠气体，让受害者产生溺水幻觉并因极度恐惧导致心脏骤停，同时用特殊装置吸收所有水分。",
        "emotional_tone": "紧张解谜",
        "key_scenes": ["实验室重现", "密室机关发现", "物理解释验证"]
      },
      {
        "chapter_number": 9,
        "chapter_title": "规则的终结",
        "core_event": "沈清源与白月笙合作，发现她其实是1842年心理学家的后代，一直在试图阻止规则的传播。他们联手摧毁了制造次声波的装置。",
        "emotional_tone": "合作对抗",
        "key_scenes": ["真相和解", "装置定位", "最终对决准备"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "理性的胜利",
        "core_event": "沈清源公开揭露通灵守则的科学真相，将案件定性为利用心理学知识的谋杀案。他选择将1842年档案公之于众，让历史的阴影彻底消散。",
        "emotional_tone": "释然坚定",
        "key_scenes": ["法庭陈述", "档案公开", "新生活的开始"]
      }
    ]
  }
}"}]

}

