{"files": [{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "沈清源",
      "role": "protagonist",
      "identity": "法租界首席法医",
      "traits": ["理性冷静", "执着求真", "内心孤独", "怀疑超自然", "创伤敏感"],
      "overt_motivation": "破解三起密室命案，找出真凶",
      "covert_motivation": "证明科学理性能够解释一切现象，包括看似超自然的事件",
      "secret_fear": "自己也会被不可理解的力量所控制，失去理性判断能力",
      "misperception_of_other": "认为通灵会成员都是愚昧迷信的受害者",
      "hidden_connection": "他的家族在1842年《南京条约》签订时曾参与相关外交事务"
    }
  ],
  "supporting_characters": [
    {
      "name": "周正德",
      "function": "助力",
      "identity": "法租界警察局长",
      "description": "正直但受制于租界政治的警察局长，为沈清源提供调查权限但时常警告他不要越界"
    },
    {
      "name": "白月笙",
      "function": "阻碍",
      "identity": "通灵会头目",
      "description": "神秘的通灵会女头目，声称能与死者沟通，对沈清源的科学调查充满敌意"
    },
    {
      "name": "林小川",
      "function": "助力",
      "identity": "法医助手",
      "description": "年轻的法医助手，精通现代化学和物理学，为沈清源提供技术支持"
    },
    {
      "name": "查尔斯·温斯顿",
      "function": "反转点",
      "identity": "英国领事馆档案管理员",
      "description": "掌握1842年档案秘密的英国人，在关键时刻提供关键线索"
    }
  ],
  "relationship_dynamics": "沈清源与各方势力形成复杂关系网：与周正德的合作中带有权力博弈，与白月笙的对立中隐藏着共同的秘密，与林小川的师徒关系体现科学传承，与查尔斯的接触揭示历史真相。所有关系都围绕通灵守则展开，最终指向1842年的历史原点。"
}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立民国上海租界背景，引入三起密室命案，沈清源发现通灵守则并开始调查",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "无水之溺",
        "core_event": "沈清源被召去调查第一起密室命案，死者是通灵会常客，死因溺毙但现场干燥无水。他在墙纸上发现七条通灵守则。",
        "emotional_tone": "悬疑紧张",
        "key_scenes": ["法医验尸发现异常", "密室现场勘查", "发现墙纸上的通灵守则"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "规则的陷阱",
        "core_event": "第二起命案发生，同样模式。沈清源逐条分析通灵守则，发现第三条'不可质疑规则'与第五条'必须验证真相'存在逻辑矛盾。",
        "emotional_tone": "困惑焦虑",
        "key_scenes": ["第二起命案现场", "规则逻辑分析", "与警察局长的争论"]
      },
      {
        "chapter_number": 3,
        "chapter_title": "通灵会的秘密",
        "core_event": "沈清源潜入通灵会调查，遇到神秘头目白月笙。他开始怀疑凶手就是制定规则的人，但发现所有成员都坚信规则是神启。",
        "emotional_tone": "神秘诡异",
        "key_scenes": ["通灵会集会", "与白月笙对峙", "发现成员的恐惧"]
      }
    ],
    "turning_point": "第三起命案发生，沈清源在死者手中发现一张1842年的英文报纸碎片，上面有通灵守则的早期版本。"
  },
  "act_two": {
    "description": "深入调查1842年档案，沈清源发现自己正在不自觉执行第六条规则，陷入更深的困境",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "南京条约的阴影",
        "core_event": "沈清源通过英国领事馆档案管理员查尔斯找到1842年《南京条约》签订当日的档案，发现通灵守则最早出现在一份外交备忘录中。",
        "emotional_tone": "震惊困惑",
        "key_scenes": ["档案室查阅", "发现1842年文件", "历史背景揭示"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "第六条的诅咒",
        "core_event": "沈清源意识到自己正在不自觉地执行第六条规则'独自承担真相'，他开始出现幻觉和记忆混乱，怀疑自己也被规则控制。",
        "emotional_tone": "恐惧绝望",
        "key_scenes": ["自我反思", "幻觉体验", "向助手求助"]
